import{_ as l,a0 as o,w as p,s as h,ao as d,I as t,x as e,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const E=JSON.parse('{"title":"Windows 下 Emacs 中的 zsh shell | LCTT x X-CMD","titleTemplate":false,"description":"Windows 下 Emacs 中的 zsh shell | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Windows 下 Emacs 中的 zsh shell | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Windows 下 Emacs 中的 zsh shell | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20170519 zsh shell inside Emacs on Windows","title":"Windows 下 Emacs 中的 zsh shell","tag":"201903","desc":""},"relativePath":"201903/20170519 zsh shell inside Emacs on Windows.md","filePath":"[post].md"}'),c={name:"201903/20170519 zsh shell inside Emacs on Windows.md"};function r(g,s,u,m,k,b){const i=o("Link");return p(),h("div",null,[s[15]||(s[15]=d(`<h1 id="windows-下-emacs-中的-zsh-shell" tabindex="-1">Windows 下 Emacs 中的 zsh shell <a class="header-anchor" href="#windows-下-emacs-中的-zsh-shell" aria-label="Permalink to “Windows 下 Emacs 中的 zsh shell”">​</a></h1><p><img src="https://www.onwebsecurity.com//images/zsh-shell-inside-emacs-on-windows.png" alt="zsh shell inside Emacs on Windows"></p><p>運行跨平台 shell（例如 Bash 或 zsh）的最大優勢在於你能在多平台上使用同樣的語法和腳本。在 Windows 上設置（替換）shell 挺麻煩的，但所獲得的回報遠遠超出這小小的付出。</p><p>MSYS2 子系統允許你在 Windows 上運行 Bash 或 zsh 之類的 shell。使用 MSYS2 很重要的一點在於確保搜索路徑都指向 MSYS2 子系統本身：存在太多依賴關係了。</p><p>MSYS2 安裝後默認的 shell 就是 Bash；zsh 則可以通過包管理器進行安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -Sy zsh</span></span></code></pre></div><p>通過修改 <code>etc/passwd</code> 文件可以設置 zsh 作為默認 shell，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkpasswd -c | sed -e &#39;s/bash/zsh/&#39; | tee -a /etc/passwd</span></span></code></pre></div><p>這會將默認 shell 從 bash 改成 zsh。</p><p>要在 Windows 上的 Emacs 中運行 zsh ，需要修改 <code>shell-file-name</code> 變量，將它指向 MSYS2 子系統中的 zsh 二進制文件。該二進制 shell 文件在 Emacs <code>exec-path</code> 變量中的某個地方。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(setq shell-file-name (executable-find &quot;zsh.exe&quot;))</span></span></code></pre></div><p>不要忘了修改 Emacs 的 <code>PATH</code> 環境變量，因為 MSYS2 路徑應該先於 Windows 路徑。接上一個例子，假設 MSYS2 安裝在 <code>c:\\programs\\msys2</code> 中，那麼執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(setenv &quot;PATH&quot; &quot;C:\\\\programs\\\\msys2\\\\mingw64\\\\bin;C:\\\\programs\\\\msys2\\\\usr\\\\local\\\\bin;C:\\\\programs\\\\msys2\\\\usr\\\\bin;C:\\\\Windows\\\\System32;C:\\\\Windows&quot;)</span></span></code></pre></div><p>在 Emacs 配置文件中設置好這兩個變量後，在 Emacs 中運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>M-x shell</span></span></code></pre></div><p>應該就能看到熟悉的 zsh 提示符了。</p><p>Emacs 的終端設置（eterm）與 MSYS2 的標準終端設置（xterm-256color）不一樣。這意味着某些插件和主題（提示符）可能不能正常工作 - 尤其在使用 oh-my-zsh 時。</p><p>檢測 zsh 否則在 Emacs 中運行很簡單，使用變量 <code>$INSIDE_EMACS</code>。</p><p>下面這段代碼片段取自 <code>.zshrc</code>（當以交互式 shell 模式啓動時會被加載），它會在 zsh 在 Emacs 中運行時啓動 git 插件並更改主題：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Disable some plugins while running in Emacs</span></span>
<span class="line"><span>if [[ -n &quot;$INSIDE_EMACS&quot; ]]; then</span></span>
<span class="line"><span>  plugins=(git)</span></span>
<span class="line"><span>  ZSH_THEME=&quot;simple&quot;</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>  ZSH_THEME=&quot;compact-grey&quot;</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>通過在本地 <code>~/.ssh/config</code> 文件中將 <code>INSIDE_EMACS</code> 變量設置為 <code>SendEnv</code> 變量……</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host myhost</span></span>
<span class="line"><span>SendEnv INSIDE_EMACS</span></span></code></pre></div><p>……同時在 ssh 服務器的 <code>/etc/ssh/sshd_config</code> 中設置為 <code>AcceptEnv</code> 變量……</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AcceptEnv LANG LC_* INSIDE_EMACS</span></span></code></pre></div><p>……這使得在 Emacs shell 會話中通過 ssh 登錄另一個運行着 zsh 的 ssh 服務器也能工作的很好。當在 Windows 下的 Emacs 中的 zsh 上通過 ssh 遠程登錄時，記得使用參數 <code>-t</code>，<code>-t</code> 參數會強制分配偽終端（之所以需要這樣，時因為 Windows 下的 Emacs 並沒有真正的 tty）。</p><p>跨平台，開源真是個好東西……</p><hr>`,27)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.onwebsecurity.com/configuration/zsh-shell-inside-emacs-on-windows.html"},{default:n(()=>[...s[0]||(s[0]=[e("https://www.onwebsecurity.com/configuration/zsh-shell-inside-emacs-on-windows.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),a(i,{href:"https://www.onwebsecurity.com/"},{default:n(()=>[...s[2]||(s[2]=[e("Peter Mosmans",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[4]||(s[4]=[e("lujun9972",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const C=l(c,[["render",r]]);export{E as __pageData,C as default};
